<script>
    import { onMount, onDestroy } from "svelte";
    import { Link, navigate, useLocation } from "svelte-routing";
    import allContent from "../data/content.json";

    let isOpen = false;
    let isSearchOpen = false;
    let searchTerm = "";
    let searchPanel;
    let searchInput;
    let isLight = false;
    let observer;

    const location = useLocation();

    const navItems = [
        { label: "수학", to: "/mathpage" },
        { label: "자연 과학", to: "/sciencepage" },
        { label: "컴퓨터 과학", to: "/cspage" }
    ];

    $: quickResults = allContent
        .filter((item) => {
            const keyword = searchTerm.trim().toLowerCase();
            if (!keyword) {
                return true;
            }

            const haystack = `${item.title} ${item.description} ${item.tags.join(" ")}`.toLowerCase();
            return haystack.includes(keyword);
        })
        .slice(0, 4);

    $: isHomepage = $location.pathname === "/";

    function updateObserver(homepage) {
        if (observer) {
            observer.disconnect();
            observer = null;
        }

        if (homepage) {
            setTimeout(() => {
                const blogSection = document.getElementById("blog-section");
                if (blogSection) {
                    observer = new IntersectionObserver(
                        (entries) => {
                            isLight = entries[0].isIntersecting;
                        },
                        { threshold: 0.02, rootMargin: "-60px 0px 0px 0px" }
                    );
                    observer.observe(blogSection);
                } else {
                    isLight = false;
                }
            }, 50);
        } else {
            isLight = true;
        }
    }

    $: updateObserver(isHomepage);

    function toggleMenu() {
        isOpen = !isOpen;
    }

    function toggleSearch() {
        isSearchOpen = !isSearchOpen;

        if (isSearchOpen) {
            isOpen = false;
            setTimeout(() => searchInput && searchInput.focus(), 0);
        }
    }

    function closeSearch() {
        isSearchOpen = false;
        searchTerm = "";
    }

    function goToContent(id) {
        closeSearch();
        navigate(`/content/${id}`);
    }

    function handleClickOutside(event) {
        if (isSearchOpen && searchPanel && !searchPanel.contains(event.target)) {
            closeSearch();
        }
    }

    function stopPropagation() {}

    onMount(() => {
        window.addEventListener("click", handleClickOutside);
    });

    onDestroy(() => {
        window.removeEventListener("click", handleClickOutside);
        if (observer) observer.disconnect();
    });
</script>

<header class="site-header" class:scrolled={!isHomepage}>
    <div class="nav-shell">
        <div class="left-section">
            <button class="menu-btn" on:click={toggleMenu} aria-label="Toggle menu" aria-expanded={isOpen}>
                <span class="material-symbols-outlined">menu</span>
            </button>
            <Link to="/" class="brand-link">WebLab</Link>
        </div>
        
        <div class="right-section">
            <nav class="desktop-nav">
                {#each navItems as item}
                    <Link to={item.to} class="nav-link">{item.label}</Link>
                {/each}
            </nav>
            <div class="divider"></div>
            <button class="search-btn" class:active={isSearchOpen} type="button" on:click|stopPropagation={toggleSearch}>
                <span class="material-symbols-outlined search-icon" style={isSearchOpen ? "font-variation-settings: 'FILL' 1;" : ""}>search</span>
            </button>
        </div>
    </div>

    <!-- Search Dropdown Panel -->
    {#if isSearchOpen}
        <div class="search-panel-wrapper" on:click|stopPropagation on:keydown={stopPropagation}>
            <div class="search-panel" bind:this={searchPanel}>
                <!-- Modern Search Input -->
                <div class="search-input-container">
                    <span class="material-symbols-outlined input-icon">search</span>
                    <input
                        bind:this={searchInput}
                        bind:value={searchTerm}
                        class="search-input"
                        type="text"
                        placeholder="Search math formulas, physics principles, or algorithms..."
                        aria-label="Search content"
                    />
                    <button class="close-search-btn" on:click={closeSearch}>
                        <span class="material-symbols-outlined">close</span>
                    </button>
                </div>

                <!-- Search Results Grid -->
                <div class="search-results-container">
                    <div class="results-header">
                        <h3 class="results-title">Recent & Relevant</h3>
                        {#if quickResults.length > 0}
                            <span class="results-count">View all results</span>
                        {/if}
                    </div>
                    <div class="results-grid">
                        {#each quickResults as item}
                            <button class="result-card" type="button" on:click={() => goToContent(item.id)}>
                                <div class="result-card-bg"></div>
                                <div class="result-content">
                                    <h4 class="result-title">{item.title}</h4>
                                    <p class="result-desc">{item.description}</p>
                                    <div class="result-tags">
                                        {#each item.tags.slice(0, 3) as tag}
                                            <span class="tag">{tag}</span>
                                        {/each}
                                    </div>
                                </div>
                            </button>
                        {/each}
                        {#if quickResults.length === 0}
                            <div class="empty-state">No matching content found.</div>
                        {/if}
                    </div>
                </div>
            </div>
        </div>
    {/if}

    <!-- Mobile Drawer overlay -->
    {#if isOpen}
        <div class="drawer-overlay open" on:click={toggleMenu} on:keydown={stopPropagation} tabindex="0" role="button"></div>
    {/if}

    <!-- Mobile Drawer menu -->
    <div class="mobile-drawer" class:open={isOpen}>
        <div class="mobile-drawer-header">
            <span class="brand-link">WebLab</span>
            <button class="close-menu" on:click={toggleMenu}>
                <span class="material-symbols-outlined">close</span>
            </button>
        </div>
        <div class="mobile-nav">
            {#each navItems as item}
                <Link to={item.to} class="mobile-nav-link" on:click={toggleMenu}>{item.label}</Link>
            {/each}
        </div>
    </div>
</header>

